41	/**
42	 * Tools that can cause a full-page navigation (explicitly or implicitly).
43	 *
44	 * When any of these completes successfully, the current page DOM is replaced
45	 * and the injected automation overlay is lost. BrowserManager re-injects the
46	 * overlay after every successful call to one of these tools.
47	 *
48	 * Note: chrome-devtools-mcp is a pure request/response server and emits no
49	 * MCP notifications, so listening for page-load events via the protocol is
50	 * not possible. Intercepting at callTool() is the equivalent mechanism.
51	 */
52	const POTENTIALLY_NAVIGATING_TOOLS = new Set([
53	  'click', // clicking a link navigates
54	  'click_at', // coordinate click can also follow a link
55	  'navigate_page',
56	  'new_page',
57	  'select_page', // switching pages can lose the overlay
58	  'press_key', // Enter on a focused link/form triggers navigation
59	  'handle_dialog', // confirming beforeunload can trigger navigation
60	]);
