import * as path from 'node:path';
import * as fs from 'node:fs';
import { CoreEvent, coreEvents } from './events.js';
import { Storage } from '../config/storage.js';

/** Filename of the sentinel that records the user's browser consent. */
const BROWSER_CONSENT_FILENAME = 'browser-consent-acknowledged.txt';

/** Content written to the sentinel file once consent is acknowledged. */
const CONSENT_ACKNOWLEDGED_CONTENT = 'consent acknowledged';

/**
 * Privacy notice shown to the user before the browser agent starts.
 */
const BROWSER_CONSENT_PROMPT =
  'Privacy Notice\n\n' +
  'The browser automation feature launches a Chrome browser and may collect ' +
  'data about your browsing session to power the browser agent. Google may ' +
  'process this data in accordance with the Google Privacy Policy: ' +
  'https://policies.google.com/privacy\n\n' +
  'Do you want to continue?';

/**
 * Returns the absolute path to the browser consent sentinel file.
 */
function getConsentFilePath(): string {
  return path.join(Storage.getGlobalGeminiDir(), BROWSER_CONSENT_FILENAME);
}

/**
 * Writes the browser consent sentinel file to record acknowledgement.
 */
function writeConsentFile(): void {
  const consentPath = getConsentFilePath();
  fs.mkdirSync(path.dirname(consentPath), { recursive: true });
  fs.writeFileSync(consentPath, CONSENT_ACKNOWLEDGED_CONTENT);
}

/**
 * Ensures the user has consented to the browser automation feature's data
 * collection practices before the browser agent starts.
 *
 * Behavior:
 * - If consent has already been acknowledged (sentinel file exists), returns
 *   `true` immediately.
 * - In non-interactive mode (no listeners on `coreEvents`), consent is
 *   automatically accepted, the sentinel file is written, and `true` is
 *   returned.
 * - In interactive mode (listeners on `coreEvents`), a consent request is
 *   emitted. If the user accepts, the sentinel file is written and `true` is
 *   returned. If the user declines, the sentinel file is not written and
 *   `false` is returned.
 */
export async function getBrowserConsentIfNeeded(): Promise<boolean> {
  // Already acknowledged — nothing to do.
  if (fs.existsSync(getConsentFilePath())) {
    return true;
  }

  // Non-interactive mode: no one is listening for consent requests, so
  // automatically accept and record the acknowledgement.
  if (coreEvents.listenerCount(CoreEvent.ConsentRequest) === 0) {
    writeConsentFile();
    return true;
